sys_ux_client_script.required_translations:
[
    {
        "message": "The risk event was reopened and moved to the Analyze state"
    },
    {
        "message": "The risk events were reopened and moved to the Analyze state"
    }
]

sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
async function handler({api, event, helpers, imports}) {
    var sysIds = api.context.props.sysIds;

    var templateFields = 're_opened_risk_event=true^state=2^' + 
        'reason_for_re_opening=' + api.state.reasonId + '^' + 
        'additional_comments_for_reopen=' + api.state.comments;
    var table = api.context.props.table;

    api.data.update_multiple_records.execute({
        table: table,
        query: 'sys_idIN' + sysIds,
        templateFields: templateFields
    });

    var sysIdArr = sysIds.split(",");

    var translatedMsg = "";
    if (sysIdArr.length == 1) {
        translatedMsg = await helpers.translate('The risk event was reopened and moved to the Analyze state');
    } else {    
        translatedMsg = await helpers.translate('The risk events were reopened and moved to the Analyze state');
    }

    api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
        items: [{
            icon: "info-circle-outline",
            content: translatedMsg,
            action: {
                type: "dismiss"
            }
        }]
    });
}
